    const pRect = pill.getBoundingClientRect();
    const oldLeft = pRect.left - cRect.left + container.scrollLeft;
    const oldTop = pRect.top - cRect.top + container.scrollTop;
    const oldWidth = pRect.width || newWidth;
    const oldHeight = pRect.height || newHeight;

    if (pill.__wfGlideAnim) {
      pill.__wfGlideAnim.cancel();
      pill.__wfGlideAnim = null;
    }

    pill.style.left = `${newLeft}px`;
    pill.style.top = `${newTop}px`;
    pill.style.width = `${newWidth}px`;
    pill.style.height = `${newHeight}px`;
    pill.style.opacity = "1";
    pill.__wfTargetEl = activeEl;

