    const mainEl = document.querySelector("main");
    const mainRect = mainEl ? mainEl.getBoundingClientRect() : { left: 0, width: window.innerWidth || 1200 };
    const centerX = mainRect.left + mainRect.width / 2;
    const sideThreshold = mainRect.width * 0.14;

